// The ONLY logic here is delegation. Requires @southpage/automation to be
// installed in the n8n instance and NODE_FUNCTION_ALLOW_EXTERNAL to permit it.
// Secrets come from process.env — never from the workflow JSON.
const { handleIngress, southpage } = require('@southpage/automation');

const item = $input.first().json;
const headers = item.headers || {};
const rawBody = item.body === undefined ? JSON.stringify(item) : (typeof item.rawBody === 'string' ? item.rawBody : JSON.stringify(item.body));
const body = typeof item.body === 'object' && item.body !== null ? item.body : item;

const result = await handleIngress(
  {
    rawBody,
    body,
    headers,
    meta: {
      ip: headers['x-forwarded-for'],
      userAgent: headers['user-agent'],
      referer: headers['referer'],
    },
  },
  { config: southpage, env: process.env },
);

// Hand the workflow the fields the Respond node needs.
return [{ json: result }];
